"""Data loader for our dataset generated by `my_generate_data.py`.

Expected directory layout (root = `bev_outputs/`):

- bev/<stem>.png
- depth_CAM_FRONT/<stem>.png
- depth_CAM_FRONT_LEFT/<stem>.png
- depth_CAM_FRONT_RIGHT/<stem>.png
- depth_CAM_BACK/<stem>.png
- depth_CAM_BACK_LEFT/<stem>.png
- depth_CAM_BACK_RIGHT/<stem>.png
- seg_CAM_FRONT/<stem>.png
- seg_CAM_FRONT_LEFT/<stem>.png
- seg_CAM_FRONT_RIGHT/<stem>.png
- seg_CAM_BACK/<stem>.png
- seg_CAM_BACK_LEFT/<stem>.png
- seg_CAM_BACK_RIGHT/<stem>.png

Where <stem> is `<scene_name>_<frame_token>` (as saved by the generator).
"""

from __future__ import annotations

import os
import json
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

import numpy as np
import torch
from PIL import Image
from torch.utils.data import Dataset, DataLoader


CAMERAS: Tuple[str, ...] = (
    "CAM_FRONT",
    "CAM_FRONT_LEFT",
    "CAM_FRONT_RIGHT",
    "CAM_BACK",
    "CAM_BACK_LEFT",
    "CAM_BACK_RIGHT",
)


def _camera_view_ids() -> torch.Tensor:
    """
    Stable integer ids for each camera view, matching `CAMERAS` order.
    Shape: (V,) with dtype long.
    """
    return torch.arange(len(CAMERAS), dtype=torch.long)


def _default_root_candidates() -> List[str]:
    # config.yaml in this repo uses `./bev_output`, while the generator writes `bev_outputs/`.
    return ["./bev_outputs", "./bev_output"]


def _resolve_root(root: Optional[str]) -> str:
    if root is not None:
        return root
    for cand in _default_root_candidates():
        if os.path.isdir(cand):
            return cand
    # Fall back to generator default even if it doesn't exist yet.
    return "./bev_outputs"


def _pil_to_float_tensor(img: Image.Image, *, grayscale: bool = False) -> torch.Tensor:
    """
    Convert PIL image -> float32 tensor in [0, 1].
    - If grayscale=True, returns (1,H,W)
    - Else returns (3,H,W)
    """
    if grayscale:
        img = img.convert("L")
        arr = np.array(img, dtype=np.uint8)  # (H,W)
        t = torch.from_numpy(arr).to(torch.float32) / 255.0
        return t.unsqueeze(0)

    img = img.convert("RGB")
    arr = np.array(img, dtype=np.uint8)  # (H,W,3)
    t = torch.from_numpy(arr).permute(2, 0, 1).to(torch.float32) / 255.0
    return t


def _pil_to_float_tensor_fast(img: Image.Image) -> torch.Tensor:
    # Slightly clearer/safer path using torch.tensor on a bytes view is awkward; keep a simple PIL->torch path.
    # This function is kept for potential future swap; not used right now.
    raise NotImplementedError


def _default_occ3d_candidates() -> List[str]:
    # my_generate_data.py uses this as BASE_DIR.
    return [os.environ.get("OCC3D_BASE_DIR", "").strip(), "/home/vbontal1/Downloads/Occupancy3D"]


def _resolve_occ3d_base_dir(occ3d_base_dir: Optional[str]) -> Optional[str]:
    if occ3d_base_dir is not None:
        return occ3d_base_dir
    for cand in _default_occ3d_candidates():
        if cand and os.path.isdir(cand):
            return cand
    return None


@dataclass(frozen=True)
class BEVSamplePaths:
    stem: str
    bev: str
    depth: Dict[str, str]
    seg: Dict[str, str]


class BEVDataset(Dataset):
    """Loads samples as a dict of tensors: bev, depth(6), seg(6), rgb(6), plus stem and paths."""

    def __init__(
        self,
        root: Optional[str] = None,
        *,
        resolution: Optional[int] = None,
        return_paths: bool = False,
        load_rgb: bool = True,
        occ3d_base_dir: Optional[str] = None,
        annotations_json: Optional[str] = None,
    ) -> None:
        self.root = _resolve_root(root)
        self.return_paths = return_paths
        self.resolution = resolution
        self.load_rgb = load_rgb

        self.occ3d_base_dir = _resolve_occ3d_base_dir(occ3d_base_dir) if self.load_rgb else None
        self.annotations_json = annotations_json
        self._rgb_paths_by_stem: Dict[str, Dict[str, str]] = {}

        bev_dir = os.path.join(self.root, "bev")
        if not os.path.isdir(bev_dir):
            raise FileNotFoundError(
                f"Expected BEV directory at {bev_dir}. "
                f"Did you run `my_generate_data.py` to create outputs?"
            )

        stems: List[str] = []
        for name in sorted(os.listdir(bev_dir)):
            if name.lower().endswith(".png"):
                stems.append(os.path.splitext(name)[0])

        self.samples: List[BEVSamplePaths] = []
        for stem in stems:
            bev_path = os.path.join(bev_dir, f"{stem}.png")
            depth_paths: Dict[str, str] = {}
            seg_paths: Dict[str, str] = {}
            ok = True
            for cam in CAMERAS:
                d = os.path.join(self.root, f"depth_{cam}", f"{stem}.png")
                s = os.path.join(self.root, f"seg_{cam}", f"{stem}.png")
                if not (os.path.exists(d) and os.path.exists(s)):
                    ok = False
                    break
                depth_paths[cam] = d
                seg_paths[cam] = s
            if ok and os.path.exists(bev_path):
                self.samples.append(BEVSamplePaths(stem=stem, bev=bev_path, depth=depth_paths, seg=seg_paths))

        if len(self.samples) == 0:
            raise RuntimeError(
                f"Found 0 complete samples under {self.root}. "
                f"Need `bev/<stem>.png` plus depth_/seg_ for all 6 cameras."
            )

        if self.load_rgb:
            self._build_rgb_index()

    def _build_rgb_index(self) -> None:
        """
        Builds stem -> {camera -> absolute image path} using Occupancy3D annotations.json.
        The stem format is `<scene_name>_<frame_token>`.
        
        WARNING: This function is called during dataset initialization. If called in a 
        worker process (num_workers > 0), exceptions may cause silent deadlocks.
        """
        occ3d = self.occ3d_base_dir
        if occ3d is None:
            raise FileNotFoundError(
                "RGB loading requested but Occupancy3D base dir not found. "
                "Pass `occ3d_base_dir=...` or set env var `OCC3D_BASE_DIR`."
            )

        annot_path = self.annotations_json or os.path.join(occ3d, "annotations.json")
        if not os.path.exists(annot_path):
            raise FileNotFoundError(
                f"RGB loading requested but annotations.json not found at {annot_path}. "
                f"Expected path: {annot_path}\n"
                f"Occupancy3D base dir: {occ3d}\n"
                "Pass `annotations_json=...` to override or ensure OCC3D_BASE_DIR is correct.\n"
                "If you're experiencing a hang: try setting num_workers=0 in data config."
            )

        needed = {sp.stem for sp in self.samples}
        print(f"[DataLoader] Building RGB index: loading {len(needed)} stems from {annot_path}")

        try:
            with open(annot_path, "r") as f:
                ann = json.load(f)
        except json.JSONDecodeError as e:
            raise RuntimeError(f"Failed to parse annotations.json at {annot_path}: {e}")
        except Exception as e:
            raise RuntimeError(f"Failed to load annotations.json at {annot_path}: {e}")

        scene_infos = ann.get("scene_infos", {})
        if not scene_infos:
            print(f"[DataLoader] WARNING: scene_infos is empty in {annot_path}")
        
        matched = 0
        for scene_name, scene_info in scene_infos.items():
            for frame_token, frame_data in scene_info.items():
                stem = f"{scene_name}_{frame_token}"
                if stem not in needed:
                    continue
                cam_sensor = frame_data.get("camera_sensor", {}) or {}
                cam_map: Dict[str, str] = {}
                for cam in CAMERAS:
                    if cam not in cam_sensor:
                        continue
                    rel = cam_sensor[cam].get("img_path")
                    if not rel:
                        continue
                    # Generator reads from BASE_DIR/imgs/<rel>
                    abs_path = os.path.join(occ3d, "imgs", rel)
                    cam_map[cam] = abs_path
                if len(cam_map) == len(CAMERAS):
                    self._rgb_paths_by_stem[stem] = cam_map
                    needed.remove(stem)
                    matched += 1
                    if not needed:
                        print(f"[DataLoader] Successfully matched all {matched} stems to RGB paths")
                        return
        
        if matched == 0:
            print(f"[DataLoader] WARNING: Could not match any stems to RGB paths!")
            print(f"[DataLoader] Checked {len(scene_infos)} scenes from annotations.json")
        else:
            print(f"[DataLoader] Matched {matched}/{len(self.samples)} stems to RGB paths")

    def __len__(self) -> int:
        return len(self.samples)

    def _load_image(self, path: str, *, grayscale: bool) -> torch.Tensor:
        img = Image.open(path)
        if self.resolution is not None:
            if grayscale:
                img = img.convert("L").resize((self.resolution, self.resolution), resample=Image.BILINEAR)
            else:
                img = img.convert("RGB").resize((self.resolution, self.resolution), resample=Image.BILINEAR)
        return _pil_to_float_tensor(img, grayscale=grayscale)

    def __getitem__(self, idx: int):
        sp = self.samples[idx]

        # BEV and seg are saved as color images; depth is saved as 8-bit grayscale.
        bev = self._load_image(sp.bev, grayscale=False)
        depth = torch.stack([self._load_image(sp.depth[cam], grayscale=True) for cam in CAMERAS], dim=0)  # (6,1,H,W)
        seg = torch.stack([self._load_image(sp.seg[cam], grayscale=False) for cam in CAMERAS], dim=0)  # (6,3,H,W)

        rgb = None
        if self.load_rgb:
            rgb_paths = self._rgb_paths_by_stem.get(sp.stem)
            if rgb_paths is None:
                raise KeyError(
                    f"Could not find RGB paths for stem={sp.stem} in annotations.json index. "
                    "If stems don't match, re-check generator naming or annotations."
                )
            rgb = torch.stack([self._load_image(rgb_paths[cam], grayscale=False) for cam in CAMERAS], dim=0)  # (6,3,H,W)

        item = {
            "bev": bev,  # (3,H,W) float32 [0,1]
            "depth": depth,  # (6,1,H,W) float32 [0,1]
            "seg": seg,  # (6,3,H,W) float32 [0,1]
            "rgb": rgb,  # (6,3,H,W) float32 [0,1] or None if load_rgb=False
            # (6,) long, indices align with camera ordering in `CAMERAS`
            "view_ids": _camera_view_ids(),
            "stem": sp.stem,
        }
        if self.return_paths:
            paths = {
                "bev": sp.bev,
                "depth": dict(sp.depth),
                "seg": dict(sp.seg),
            }
            if self.load_rgb:
                paths["rgb"] = dict(self._rgb_paths_by_stem.get(sp.stem, {}))
            item["paths"] = paths
        return item


def make_dataloader(
    *,
    root: Optional[str] = None,
    batch_size: int = 2,
    shuffle: bool = True,
    num_workers: int = 0,
    drop_last: bool = False,
    resolution: Optional[int] = None,
    load_rgb: bool = True,
    occ3d_base_dir: Optional[str] = None,
    annotations_json: Optional[str] = None,
) -> DataLoader:
    ds = BEVDataset(
        root=root,
        resolution=resolution,
        load_rgb=load_rgb,
        occ3d_base_dir=occ3d_base_dir,
        annotations_json=annotations_json,
    )
    return DataLoader(
        ds,
        batch_size=batch_size,
        shuffle=shuffle,
        num_workers=num_workers,
        drop_last=drop_last,
        pin_memory=True,
    )